INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 4 FROM countries WHERE code = 'LT';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '2024', 'SABIS replaces the legacy "E. sąskaita" B2G platform');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE code = 'LT';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'B2G format & platform (SABIS)', '[["Format", "EN 16931-compliant structured e-invoice"], ["Platform", "SABIS (Sąskaitų administravimo bendroji informacinė sistema), replacing the legacy \"E. sąskaita\" system in 2024"], ["Transmission", "Manual portal entry, or Peppol BIS Billing 3.0 / CII"], ["Scope", "All public procurement contracts, above and below EU thresholds"]]', 'Lithuania''s B2G scope is broader than most EU peers -- it applies to every public procurement contract, not just those above the EU''s procurement thresholds.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE code = 'LT';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'i.SAF reporting format (separate from invoicing)', '[["Form", "FR0600 -- structured VAT invoice ledger"], ["Content", "Sales register (all invoices issued) and purchase register (invoices received from LT VAT payers, plus reverse-charge transactions)"], ["Frequency", "Monthly, due by the 20th of the following month"], ["Nil filing", "Required even when no invoices were issued"]]', 'i.SAF is a periodic report about your invoices, filed to VMI after the fact -- it does not change what format you must use to actually issue an invoice to a customer, and it is not a real-time or clearance system.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE code = 'LT';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What''s covered today', '[["B2G", "All public procurement suppliers, no minimum contract value -- mandatory since 1 Jul 2017"], ["i.SAF (VAT reporting)", "Every VAT-registered entity, domestic or foreign, no size threshold -- since ~Oct 2016"], ["B2B invoicing itself", "No mandate of any kind -- entirely voluntary, by mutual agreement"], ["B2C", "Not covered by any e-invoicing or reporting rule"]]', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE code = 'LT';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'The disputed "2028" B2B target, explained', '[["Where it appears", "The European Commission''s own 2025 Lithuania eInvoicing Country Sheet"], ["The contradiction", "The same factsheet page also states outright: \"There is no business-to-business (B2B) mandate\""], ["What corroborates it", "No enacted Lithuanian law, VMI order, or Seimas act was found anywhere confirming a 2028 mandate"], ["A plausible explanation", "Neighbouring Latvia has a real, separately-enacted B2B mandate confirmed postponed to exactly 1 Jan 2028 (KPMG, June 2025) -- several industry sources repeating \"Lithuania 2028\" may be echoing this, the ambiguous factsheet wording, or both"]]', 'This card exists specifically so a reader encountering the "2028" figure elsewhere understands why this page does not treat it as confirmed.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE code = 'LT';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚖️ No B2B e-invoicing fine exists — because no B2B mandate exists', NULL, NULL, 'There is nothing to penalize on the invoicing side: Lithuania has never legislated a B2B e-invoicing or clearance requirement, so no fine schedule attaches to how you issue or exchange invoices with another business.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE code = 'LT';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📋 i.SAF penalty figures are unresolved -- not stated here', NULL, NULL, 'Two industry sources give different euro bands for late or missing i.SAF/SAF-T filings, and neither was independently confirmed against the current Administrative Offences Code text this research round (direct fetches of Lithuania''s official legal database failed). Rather than present either figure as settled, this page confirms only that a general VAT-underpayment penalty of 20-100% of unpaid tax applies under the VAT Law and Tax Administration Law, and that administrative penalties for tax-document non-submission exist in principle under an amended Administrative Offences Code article.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE code = 'LT';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your B2G invoicing already runs through SABIS', 'If you supply Lithuanian public bodies, verify your invoices are structured EN 16931 e-invoices submitted via SABIS -- the platform that replaced the legacy E. sąskaita system in 2024.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE code = 'LT';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Set up monthly i.SAF filing if you''re VAT-registered in Lithuania', 'Confirm your accounting software can produce a compliant FR0600 sales/purchase VAT ledger, due by the 20th of the following month -- there is no size exemption, and a nil report is required even in a month with no invoices.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE code = 'LT';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Don''t confuse i.SAF with an e-invoicing mandate', 'i.SAF changes what accounting data you report and when -- it does not require you to change how you issue or exchange invoices with other businesses, since no B2B e-invoicing mandate exists in Lithuania today.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE code = 'LT';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Treat the "2028" figure as a watch item, not a deadline', 'Don''t build compliance plans around a confirmed 1 January 2028 Lithuanian B2B mandate -- it isn''t confirmed. Monitor VMI and the Ministry of Finance for an actual enacted law before treating any date as real.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE code = 'LT';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Prepare for the confirmed 2030 EU floor regardless', 'Whatever happens domestically, structured e-invoicing and digital reporting become mandatory for cross-border intra-EU B2B trade from 1 July 2030 under ViDA -- that date is settled EU law.');
